 "content": "from collections import deque

def transform(grid):
    """Recolor large solid monochromatic rectangular patches to 4."""
    h, w = len(grid), len(grid[0])
    seen = [[False] * w for _ in range(h)]
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            minr = min(y for y, x in cells)
            maxr = max(y for y, x in cells)
            minc = min(x for y, x in cells)
            maxc = max(x for y, x in cells)
            area = (maxr-minr+1) * (maxc-minc+1)
            if area >= 25 and len(cells) == area:
                for y, x in cells:
                    out[y][x] = 4
    return out
