 "content": "from collections import defaultdict

def transform(grid):
    """Recolor all maximal solid monochrome rectangles of at least 5x5 to 4."""
    h, w = len(grid), len(grid[0])
    candidates = []
    # Enumerate rectangles via row bands and color-specific contiguous column runs.
    for top in range(h):
        common = [True] * w
        for bottom in range(top, h):
            for c in range(w):
                common[c] = common[c] and grid[bottom][c] == grid[top][c]
            # Extend constant-colored horizontal runs across every row in this band.
            c = 0
            while c < w:
                color = grid[top][c]
                if not common[c]:
                    c += 1
                    continue
                end = c + 1
                while end < w and common[end] and grid[top][end] == color:
                    end += 1
                height, width = bottom-top+1, end-c
                if height >= 5 and width >= 5:
                    candidates.append((top,bottom,c,end,color))
                c = end
    # Keep maximal qualifying rectangles, allowing adjacent same-color cells outside
    # the chosen rectangle only when they would enlarge it as a whole.
    maximal = []
    for rect in candidates:
        t,b,l,r,color = rect
        if any(color == other[4] and other != rect and
               other[0] <= t and other[1] >= b and other[2] <= l and other[3] >= r
               for other in candidates):
            continue
        maximal.append(rect)
    out = [row[:] for row in grid]
    for t,b,l,r,color in maximal:
        for y in range(t,b+1):
            for x in range(l,r):
                out[y][x] = 4
    return out
"
}

