 "content": "def transform(grid):
    """Fill each maximal solid monochromatic rectangle of area >= 25 with 4."""
    h, w = len(grid), len(grid[0])
    rectangles = []
    # Enumerate color-constant rectangles for each row band.
    for top in range(h):
        common = [True] * w
        for bottom in range(top, h):
            for c in range(w):
                common[c] = common[c] and grid[bottom][c] == grid[top][c]
            c = 0
            while c < w:
                color = grid[top][c]
                if not common[c]:
                    c += 1
                    continue
                end = c + 1
                while end < w and common[end] and grid[top][end] == color:
                    end += 1
                if (bottom - top + 1) * (end - c) >= 25:
                    rectangles.append((top, bottom, c, end, color))
                c = end
    out = [row[:] for row in grid]
    for top, bottom, left, right, color in rectangles:
        # Ignore any candidate that can be enlarged by a whole adjacent side.
        if left > 0 and all(grid[r][left - 1] == color for r in range(top, bottom + 1)):
            continue
        if right < w and all(grid[r][right] == color for r in range(top, bottom + 1)):
            continue
        if top > 0 and all(grid[top - 1][c] == color for c in range(left, right)):
            continue
        if bottom + 1 < h and all(grid[bottom + 1][c] == color for c in range(left, right)):
            continue
        for r in range(top, bottom + 1):
            for c in range(left, right):
                out[r][c] = 4
    return out
"
}

